[[module CSS]]

:root {

  --brass: 138, 109, 47;

  --ink-rgb: 22, 24, 27;

  --medium-accent: var(--brass);

  --dark-accent: var(--ink-rgb);

  --bright-accent: var(--brass);

  --cutColour: #f7f5f0;

  --barColour: var(--brass);

  --toggle-border-color: rgb(var(--brass));

  --toggle-icon-color: rgb(var(--brass));

  --mono-font: 'IBM Plex Mono', monospace;

  --background-gradient-distance: 20rem;

  --background-gradient-color: var(--brass);

  --link-color: 138, 109, 47;

  --visited-link-color: 110, 86, 36;

  --hover-link-color: 90, 70, 28;

}



#page-content {

  --doc-line: #d9d4c7;

  --doc-soft: #e6e1d5;

  --doc-panel: #f3f1ec;

  --doc-paper: #fbfaf6;

  --doc-ink: #16181b;

  --doc-muted: #6d685d;

  --doc-accent: #8a6d2f;

  --s7-ink: #16181b;

  --s7-bone: #f7f5f0;

  --s7-stone: #d9d4c7;

  --s7-brass: #8a6d2f;

  --s7-alarm: #b3261e;

}



#content-wrap {

  background-color: #f7f5f0;

  background-image:

    linear-gradient(rgb(22 24 27 / 0.04) 1px, transparent 1px),

    linear-gradient(90deg, rgb(22 24 27 / 0.04) 1px, transparent 1px);

  background-size: 32px 32px;

}



.info-container { --barColour: #8a6d2f; }



#page-content .scp-image-block {

  border: none;

  border-bottom: 2px solid var(--s7-brass);

  box-shadow: none;

}



#page-content .wiki-content-table {

  border-collapse: collapse;

  background: #fff;

}

#page-content .wiki-content-table th {

  background: var(--s7-ink) !important;

  color: var(--s7-bone) !important;

  font-size: 0.85em;

  letter-spacing: 0.12em;

  text-align: center;

}

#page-content .wiki-content-table td {

  background: #fff;

  border: 1px solid var(--s7-stone);

}



#page-content .addendum {

  width: auto;

  margin: 1.5em 0;

  padding: 0 1.25em 1em;

  background: #fff;

  border: 1px solid var(--s7-stone);

  border-top: 4px solid var(--s7-ink);

  box-shadow: var(--doc-shadow);

}

#page-content .addendum > [style*="center"]:first-child,

#page-content .addendum > [style*="center"]:first-child p { margin: 0.9em 0 0.6em; }

#page-content .addendum > [style*="center"]:first-child strong {

  font-size: 0.8em;

  letter-spacing: 0.2em;

  color: var(--doc-muted);

}

#page-content .addendum .interview { width: auto; }



#page-content .snip {

  width: auto;

  margin: 0.9em 0;

  padding: 0.4em 1.1em 0.6em;

  background: var(--doc-paper);

  border: none;

  border-left: 3px solid var(--s7-brass);

}

#page-content .snip hr { background: var(--doc-soft) !important; }

#page-content .snip > [style*="center"]:first-child strong,

#page-content .snip > p[style*="center"]:first-child {

  font-size: 0.82em;

  font-weight: 700;

  letter-spacing: 0.16em;

  color: var(--s7-brass);

}

#page-content .snip .wiki-content-table {

  width: 100%;

  margin: 0.4em 0;

  font-size: 0.92em;

}

#page-content .snip .wiki-content-table td { text-align: center; }



#page-content .dation {

  position: relative;

  width: auto;

  margin: 2em 0;

  padding: 1.5em 1.25em 0.7em;

  background: #fff;

  border: 1px solid #e3c7c3;

  border-left: 6px solid var(--s7-alarm);

  box-shadow: var(--doc-shadow);

  color: var(--s7-ink);

  font-weight: normal;

}

#page-content .dation::before {

  content: "";

  position: absolute;

  top: 0;

  left: 0;

  right: 0;

  height: 8px;

  background: repeating-linear-gradient(-45deg, var(--s7-alarm) 0 10px, var(--s7-ink) 10px 20px);

}

#page-content .dation > [style*="center"]:first-child,

#page-content .dation > [style*="center"]:first-child p { margin: 0.1em 0 0.4em; }

#page-content .dation > [style*="center"]:first-child * {

  color: var(--s7-alarm) !important;

  font-size: 1.05em !important;

  font-weight: 800;

  letter-spacing: 0.14em;

}



#page-content .one {

  position: relative;

  width: auto;

  margin: 2em 0;

  padding: 1.1em 1.4em 1em;

  background: #0f1113;

  color: #f0b429;

  border: 1px solid #000;

  font-family: var(--mono-font);

  font-size: 0.92em;

  font-weight: normal;

  text-shadow: 0 0 6px rgb(240 180 41 / 0.35);

  box-shadow: inset 0 0 30px rgb(0 0 0 / 0.8), var(--doc-shadow);

}

#page-content .one [style*="center"] { text-align: left !important; }

#page-content .one strong { color: #ffd166; }

#page-content .one::after {

  content: "▌";

  animation: s7-blink 1s steps(1) infinite;

}

@keyframes s7-blink { 50% { opacity: 0; } }



#page-content .interview.void {

  background: radial-gradient(ellipse at 50% 0%, #2a2218 0%, #0b0c0d 70%);

  color: #e9e4d6;

  border: 1px solid #000;

}

#page-content .interview.void strong { color: #fff; }

#page-content .interview.void em { color: #cfc6b3; }

#page-content .interview.void hr { background: #3a342a !important; }



@media (max-width: 768px) {

  #page-content .addendum,

  #page-content .dation,

  #page-content .one { padding-left: 1em; padding-right: 1em; }

}

