[[include <a href="/component:image-block">component:image-block</a>

|name=https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Ancient_Egypt_Jewelry%2C_New_Kingdom_%2827798071253%29.jpg/500px-Ancient_Egypt_Jewelry%2C_New_Kingdom_%2827798071253%29.jpg?20210309010254

